    this.value = value
    this.next = null
  }
}

class LinkedList {
  constructor(value) {
    this.head = null
    this.tail = null
    this.length = 0
    if (value !== undefined) {
      const newNode = new Node(value)
      this.head = newNode
      this.tail = this.head
      this.length = 1
    }
  }

  push(value) {
    const newNode = new Node(value)
    if (!this.head) {
      this.head = newNode
      this.tail = newNode
    } else {
      this.tail.next = newNode
      this.tail = newNode
    }
    this.length++
    return this
  }

  reverse() {
    // 1. swap head and tail (temp remembers the old head)
    // 2. prev starts as null, and so does next
    // 3. for each node: next = temp.next, to remember the rest
    // 4.   temp.next = prev: flip the arrow
    // 5.   prev = temp, then temp = next: both move one node on
    // 6. return the list
  }

  // our helper: the values from head to tail, as an array
  toArray() {
    const values = []
    let temp = this.head
    while (temp !== null) {
      values.push(temp.value)
      temp = temp.next
    }
    return values
  }
}

